import {call,subscribe,preview,loadRuntimePlatform,observePendingTransfer,operationHandled,markOperationHandled,type TransferSnapshot,type Entry} from './api';
import {escapeHtml as esc,icon} from './icons';
import QRCode from 'qrcode';
import {getCurrent,onOpenUrl} from '@tauri-apps/plugin-deep-link';
import {currentLanguage,errorText} from './i18n';
import {automaticActions,configuredServer,invitationSeconds,type TransferPreferences} from './transfer-policy';

const t=(ru:string,en:string)=>currentLanguage()==='ru'?ru:en;
type Peer={id:string;name:string;online:boolean};
type Offer={id:string;name:string;size:number;from:string};
type State={connection?:{server:string};device:{id:string;name:string};peers:Peer[];pairRequests:{id:string;name:string}[];offers:Offer[]};
let state:State|null=null,connected=false,server=configuredServer(localStorage.getItem('hearfolio-relay-url')),name=localStorage.getItem('hearfolio-device-name')||'',code='',codeUntil=0,message='',polling=false,operation=false,session='',offset=0,total=0,phase='';
type Pending={id:string;to:string;name:string;server:string};
let pending:Pending|null=null,connectionSaved=false,connectionError=false,connectionPaused=localStorage.getItem('hearfolio-transfer-paused')==='true',pairMode:'invite'|'code'='invite',setupMode:'first'|'join'='first';
try {const saved=JSON.parse(localStorage.getItem('hearfolio-pending-transfer')||'null');if(saved&&typeof saved.id==='string'&&typeof saved.to==='string'&&typeof saved.server==='string'&&typeof saved.name==='string')pending=saved;}catch{/* Ignore invalid queue state. */}
function savePending(){if(pending)localStorage.setItem('hearfolio-pending-transfer',JSON.stringify(pending));else localStorage.removeItem('hearfolio-pending-transfer');}
const preferences:TransferPreferences={autoPair:localStorage.getItem('hearfolio-auto-pair')==='true',autoReceive:localStorage.getItem('hearfolio-auto-receive')==='true'};
const autoAttempted=new Set<string>();let autoProcessing=false;
let scannerAvailable=false,scanning=false,backgroundEnabled=localStorage.getItem('hearfolio-background-receive')==='true',backgroundActive=false;
let pairingWait:{known:string[];until:number}|null=null;
let options:{refresh:()=>Promise<unknown>;busy:()=>boolean;setBusy:(value:boolean)=>void;notice:(message:string,error?:boolean)=>void;confirm:(heading:string,message:string)=>Promise<boolean>}|null=null;
const fixture=import.meta.env.DEV&&preview&&new URLSearchParams(location.search).get('devices')==='fixture';
const fixtureState:State={device:{id:'fixture-this-device',name:'MacBook Анны'},peers:[{id:'fixture-phone',name:'Телефон Анны',online:true},{id:'fixture-laptop',name:'Домашний ноутбук',online:false}],pairRequests:[],offers:[{id:'fixture-offer',name:'Обсуждение проекта',size:2457600,from:'Телефон Анны'}]};
let fixtureCounter=0;
let networkWaiting=false;
let nativeTransferId='',transferSnapshotPolling=false,foregroundTransfer=false;

async function fixtureApi(action:string,payload:unknown){const data=payload as Record<string,unknown>;if(action==='saved')return {server,configured:true};if(action==='code')return {code:'12345678',expiresAt:Date.now()+(new URLSearchParams(location.search).get('invitation')==='expired'?-1000:180000)};if(action==='confirmPair'){fixtureState.pairRequests=fixtureState.pairRequests.filter(p=>p.id!==data.id);if(data.accept)fixtureState.peers.push({id:`fixture-paired-${++fixtureCounter}`,name:'Новое устройство',online:true});}if(action==='cancel')fixtureState.offers=fixtureState.offers.filter(p=>p.id!==data.id);if(action==='unpair')fixtureState.peers=fixtureState.peers.filter(p=>p.id!==data.id);if(action==='pair'){fixtureState.pairRequests=[{id:'fixture-pair-request',name:'Новое устройство'}];}return structuredClone(fixtureState);}
const api=<T>(action:string,payload:unknown={})=>fixture?fixtureApi(action,payload) as Promise<T>:call<T>('transfer_api',{action,payload});
let connectionDraft:{server:string;name:string;accessKey:string}|null=null;
export function hasTransferDraft(){return Boolean(connectionDraft&&(Boolean(connectionDraft.server&&configuredServer(connectionDraft.server)!==server)||connectionDraft.name.trim()!==name||connectionDraft.accessKey));}
export function discardTransferDraft(){connectionDraft=null;}
function rememberConnectionDraft(form:HTMLFormElement){const data=new FormData(form);connectionDraft={server:String(data.get('server')||''),name:String(data.get('name')||''),accessKey:String(data.get('accessKey')||'')};}
function clearConnectionDraft(){connectionDraft=null;document.querySelectorAll<HTMLInputElement>('input[name="accessKey"]').forEach(input=>input.value='');}

function statusText(){if(networkWaiting&&operation)return t('Ищем устройство в локальной сети…','Finding your device on the local network…');const labels:Record<string,string>={waiting:t('Ожидает подтверждения','Waiting for acceptance'),sending:t('Отправка','Sending'),receiving:t('Получение','Receiving'),delivered:t('Доставлено','Delivered')};return labels[phase]||phase;}
export function transferActivityLabel(){return operation?statusText():'';}
function senderName(from:string){return state?.peers.find(peer=>peer.id===from||peer.name===from)?.name||t('подключённого устройства','a paired device');}
function requestsHtml(){if(connectionPaused)return '';return `${state?.pairRequests.map(p=>`<div class="transfer-request transfer-offer"><span class="transfer-offer-icon">${icon('devices')}</span><div class="transfer-offer-info"><strong>${esc(p.name)}</strong><small>${t('Хочет подключиться к этому устройству. Подтвердите, если узнаёте его.','Wants to pair with this device. Accept if you recognize it.')}</small></div><div class="transfer-offer-actions"><button class="secondary" data-pair-accept="${esc(p.id)}">${t('Подключить','Accept')}</button><button class="text-button" data-pair-reject="${esc(p.id)}">${t('Отклонить','Decline')}</button></div></div>`).join('')||''}${state?.offers.map(p=>`<div class="transfer-request transfer-offer"><span class="transfer-offer-icon">${icon('download')}</span><div class="transfer-offer-info"><strong>${esc(p.name)}</strong><small>${t('От','From')} ${esc(senderName(p.from))} · ${formatSize(p.size)}</small>${options?.busy()?`<small>${t('Запись можно принять после завершения текущей операции.','Receive this recording when the current operation finishes.')}</small>`:''}</div><div class="transfer-offer-actions"><button class="secondary" data-receive="${esc(p.id)}" ${options?.busy()?'disabled':''}>${t('Принять запись','Receive recording')}</button><button class="text-button" data-reject="${esc(p.id)}">${t('Отклонить','Decline')}</button></div></div>`).join('')||''}`;}
function formatSize(size:number){return size<1048576?`${Math.ceil(size/1024)} ${t('КБ','KB')}`:`${(size/1048576).toFixed(1)} ${t('МБ','MB')}`;}
function expiryText(){const seconds=invitationSeconds(codeUntil,Date.now());return seconds?`${t('Одноразовый код · ещё','One-time code · expires in')} ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:t('Код истёк — обновите приглашение','Code expired — renew invitation');}
function connectionText(){if(!server&&connectionSaved&&!connectionPaused)return t('Подключитесь к локальной сети','Connect to a local network');return connectionPaused?t('Передача выключена','Transfers paused'):preview&&!fixture?t('Настройки сохранены · предпросмотр','Settings saved · preview'):connected&&!connectionError?t('Готово к передаче','Ready to transfer'):t('Ищем подключённое устройство…','Finding your paired device…');}
function serverLabel(){try{return new URL(server).host;}catch{return server;}}
function messageHtml(){return message?`<div class="transfer-feedback" role="status">${esc(message)}</div>`:'';}
function preserveFields(root:Element){return [...root.querySelectorAll<HTMLInputElement>('input')].map(input=>({form:input.form?.id||'',name:input.name,value:input.value,focused:input===document.activeElement,selection:input.selectionStart})).filter(input=>input.name);}
function restoreFields(root:Element,fields:ReturnType<typeof preserveFields>){for(const field of fields){const input=[...root.querySelectorAll<HTMLInputElement>('input')].find(input=>input.name===field.name&&(input.form?.id||'')===field.form);if(!input||input.type==='checkbox')continue;input.value=field.value;if(field.focused){input.focus({preventScroll:true});if(field.selection!==null&&input.type!=='url')try{input.setSelectionRange(field.selection,field.selection);}catch{/* Some input types do not support a selection. */}}}}

export function shareButtonHtml(){return `<button class="icon-button" id="transfer-send" title="${t('Поделиться','Share')}" aria-label="${t('Поделиться','Share')}" ${operation||options?.busy()?'disabled':''}>${icon('share')}</button>`;}
export function transferBarHtml(_entry:Entry|null){return `<div class="transfer-bar" id="transfer-bar" ${!notificationsHtml()?'hidden':''}><div id="transfer-notifications">${notificationsHtml()}</div></div>`;}
function operationHtml(){return operation?`<div class="transfer-operation"><div><strong role="status">${esc(statusText())}${total?` · ${Math.floor(offset/total*100)}%`:''}</strong>${phase==='waiting'?`<small>${t('Примите запись на другом устройстве','Accept the recording on your other device')}</small>`:''}${total?`<progress max="${total}" value="${offset}" aria-label="${t('Передача записи','Recording transfer')}"></progress>`:''}</div><button class="text-button" id="transfer-cancel" ${!session&&!nativeTransferId?'disabled':''}>${t('Отменить','Cancel')}</button></div>`:'';}
function notificationsHtml(){return `${operationHtml()}${requestsHtml()}`;}
function update(){updateTransferSettings();const notice=document.querySelector('#transfer-notifications');if(notice){notice.innerHTML=notificationsHtml();notice.parentElement!.hidden=!notice.innerHTML;bindRequests(notice);}updateShareDialog();updateDevicesPanel();document.querySelectorAll<HTMLButtonElement>('#transfer-send').forEach(b=>b.disabled=operation||Boolean(options?.busy()));}
async function runAction(action:string,payload:unknown={}){try{await api(action,payload);if(action==='confirmPair'&&(payload as {accept?:boolean}).accept){shareView='devices';code='';qr='';codeUntil=0;message=t('Устройство подключено','Device paired');if(!shareEntry)shareDialog?.close();}if(action==='pair'){pairingWait={known:state?.peers.map(p=>p.id)||[],until:Date.now()+180000};message=t('Запрос отправлен. Подтвердите подключение на втором устройстве.','Request sent. Confirm pairing on the other device.');}await poll();}catch(e){message=errorText(e);update();}}
function bindRequests(root:Element){root.querySelectorAll<HTMLElement>('[data-pair-accept]').forEach(b=>b.onclick=()=>{void runAction('confirmPair',{id:b.dataset.pairAccept,accept:true});});root.querySelectorAll<HTMLElement>('[data-pair-reject]').forEach(b=>b.onclick=()=>{void runAction('confirmPair',{id:b.dataset.pairReject,accept:false});});root.querySelectorAll<HTMLElement>('[data-reject]').forEach(b=>b.onclick=()=>{void runAction('cancel',{id:b.dataset.reject});});root.querySelectorAll<HTMLElement>('[data-receive]').forEach(b=>b.onclick=()=>{void receive(b.dataset.receive!);});root.querySelector('#transfer-cancel')?.addEventListener('click',cancelTransfer);}
function bindPanel(){document.querySelector('#transfer-discard')?.addEventListener('click',()=>{pending=null;savePending();update();});document.querySelector('#transfer-retry')?.addEventListener('click',()=>{if(pending&&state?.peers.some(peer=>peer.id===pending?.to))void transfer('transfer_send',{id:pending.id,to:pending.to});else options?.notice(t('Подключитесь к тому же устройству для повторной отправки','Connect to the same device to retry'),true);});document.querySelector('#transfer-code')?.addEventListener('click',async()=>{try{const result=await api<{code:string;expiresAt:number}>('code');code=result.code;codeUntil=result.expiresAt;update();}catch(e){message=errorText(e);update();}});document.querySelector<HTMLFormElement>('#transfer-pair')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget as HTMLFormElement;void runAction('pair',{code:String(new FormData(form).get('code')).replace(/\s/g,'')});});document.querySelectorAll<HTMLElement>('[data-unpair]').forEach(b=>b.onclick=async()=>{if(await options?.confirm(t('Отключить устройство?','Unpair device?'),t('Для следующей передачи потребуется подключить его снова.','Pair it again before the next transfer.')))void runAction('unpair',{id:b.dataset.unpair});});const panel=document.querySelector('#transfer-state');if(panel)bindRequests(panel);}
function bindConnection(){document.querySelectorAll<HTMLFormElement>('#transfer-connect').forEach(form=>{form.querySelectorAll<HTMLInputElement>('input').forEach(input=>input.oninput=()=>rememberConnectionDraft(form));form.onsubmit=async e=>{e.preventDefault();if(operation||modalWorking)return;const data=new FormData(form);await modalAction(async()=>{if(setupMode==='join'&&data.get('invitationCode'))await joinInvitation(data);else{await connectRelay(data);message=preview?t('Настройки сохранены. Передача доступна в приложении Hearfolio.','Settings saved. Transfer is available in the Hearfolio app.'):t('Подключено. Теперь можно добавить второе устройство.','Connected. You can now add another device.');options?.notice(message);}});};});}

function bindBackground(){const background=document.querySelector<HTMLInputElement>('#background-receive');if(background)background.onchange=async()=>{backgroundEnabled=background.checked;localStorage.setItem('hearfolio-background-receive',String(backgroundEnabled));await syncBackground();background.checked=backgroundEnabled;};}
export function bindTransfers(entry:Entry|null){bindBackground();bindConnection();bindPanel();bindDevicesActions();const notifications=document.querySelector('#transfer-notifications');if(notifications)bindRequests(notifications);document.querySelector('#transfer-send')?.addEventListener('click',()=>{if(entry)chooseRecipient(entry);});}
let shareDialog:HTMLDialogElement|null=null,shareEntry:Entry|null=null,shareView:'devices'|'pair'='devices',qr='',modalWorking=false;
function scanButtonHtml(){return scannerAvailable?`<button type="button" class="secondary" data-scan-invitation ${scanning||modalWorking?'disabled':''}>${icon('qr')}${t('Сканировать QR','Scan QR')}</button>`:'';}
function bindScanner(root:ParentNode){root.querySelectorAll<HTMLElement>('[data-scan-invitation]').forEach(button=>button.onclick=()=>{void scanDeviceInvitation();});}
async function scanDeviceInvitation(){if(scanning||modalWorking||operation||options?.busy())return;scanning=true;const dialog=shareDialog;if(dialog?.open)dialog.close();try{if(preview){options?.notice(t('Камера доступна в Android-приложении.','The camera is available in the Android app.'));return;}const {scanInvitation}=await import('./qr-scanner');const raw=await scanInvitation();if(raw){let url:URL;try{url=new URL(raw);}catch{throw new Error('errors.qrInvitationInvalid');}if(url.protocol!=='hearfolio-transfer:'||url.hostname!=='pair'||!/^\d{8}$/.test(url.searchParams.get('code')||'')||!url.searchParams.get('server'))throw new Error('errors.qrInvitationInvalid');await acceptInvitation(raw);}}catch(e){message=errorText(e);options?.notice(message,true);}finally{scanning=false;update();}}
function deviceNameField(){return `<label class="field"><span>${t('Имя этого устройства','This device name')}</span><input name="name" required maxlength="100" autocomplete="off" value="${esc(connectionDraft?.name??name)}" placeholder="${t('Например, MacBook Анны','For example, Anna’s MacBook')}"><small>${t('Это имя увидят на другом устройстве.','This name appears on your other devices.')}</small></label>`;}
function serverField(value=connectionDraft?.server??server){return `<label class="field"><span>${t('Адрес другого устройства','Other device address')}</span><input name="server" type="url" required autocomplete="off" value="${esc(value)}" placeholder="http://192.168.1.10:47831"><small>${t('Адрес показан под QR на другом устройстве. Оба устройства должны быть в одной локальной сети.','The address is shown below the QR on your other device. Both devices must be on the same local network.')}</small></label>`;}
function codeField(){return `<label class="field"><span>${t('Код с другого устройства','Code from another device')}</span><input name="invitationCode" required inputmode="numeric" pattern="[0-9 ]{8,9}" maxlength="9" autocomplete="one-time-code" placeholder="1234 5678"></label>`;}
function connectFields(){return deviceNameField();}
function setupFormHtml(){return `<div class="transfer-setup"><span class="transfer-setup-icon">${icon('devices')}</span><h2>${t('Подключите ваши устройства','Connect your devices')}</h2><p>${t('Подключите оба устройства к одной Wi-Fi сети. Назовите первое устройство и покажите на нём приглашение.','Connect both devices to the same Wi-Fi network. Name your first device, then show an invitation on it.')}</p><div class="transfer-tabs" role="group" aria-label="${t('Способ подключения','Connection method')}"><button type="button" data-setup-mode="first" aria-pressed="${setupMode==='first'}">${t('Первое устройство','First device')}</button><button type="button" data-setup-mode="join" aria-pressed="${setupMode==='join'}">${t('Есть приглашение','Have an invitation')}</button></div><form id="transfer-connect">${setupMode==='first'?connectFields():`${serverField()}${deviceNameField()}${codeField()}`}<button class="primary" ${modalWorking?'disabled':''}>${modalWorking?t('Подключение…','Connecting…'):setupMode==='first'?t('Включить локальную передачу','Enable local transfers'):t('Подключить по приглашению','Join with invitation')}</button></form>${setupMode==='join'?scanButtonHtml():''}${messageHtml()}</div>`;}

function backgroundSettingsHtml(){return scannerAvailable?`<div class="transfer-preferences"><label class="transfer-preference"><span><strong>${t('Ожидать передачи в фоне','Wait for transfers in background')}</strong><small>${t('Работает при свёрнутом приложении и блокировке экрана. Постоянное уведомление позволяет выключить ожидание. После длительного ожидания или перезапуска телефона откройте приложение снова. Расходует заряд.','Works with the app minimized and screen locked. Turn off waiting from the persistent notification. Open the app again after prolonged waiting or restarting the phone. Uses battery.')}</small></span><input type="checkbox" role="switch" id="background-receive" ${!connected||connectionPaused?'disabled':''} ${backgroundEnabled?'checked':''}><i aria-hidden="true"></i></label></div>`:'';}
type InboxSnapshot={enabled:boolean;error?:string|null;result?:{id:string;ok:boolean;error?:string|null}|null};
let lastInboxError='';
const inboxReceiptsInFlight=new Set<string>();
async function consumeInboxSnapshot(snapshot:InboxSnapshot){
  backgroundActive=snapshot.enabled;
  if(snapshot.result?.id){
    const receipt=`${server}:${snapshot.result.id}:${snapshot.result.ok}`;
    if(localStorage.getItem('hearfolio-last-background-receipt')!==receipt&&!inboxReceiptsInFlight.has(receipt)){
      inboxReceiptsInFlight.add(receipt);
      try{
        await options?.refresh();localStorage.setItem('hearfolio-last-background-receipt',receipt);
        options?.notice(snapshot.result.ok?t('Запись получена и добавлена в архив','Recording received and added to your archive'):errorText(snapshot.result.error||'errors.transferBackgroundUnavailable'),!snapshot.result.ok);
      }finally{inboxReceiptsInFlight.delete(receipt);}
    }
  }
  if(snapshot.error&&snapshot.error!==lastInboxError){lastInboxError=snapshot.error;options?.notice(errorText(snapshot.error),true);}
  if(!snapshot.error)lastInboxError='';
  if(backgroundEnabled&&!snapshot.enabled){backgroundEnabled=false;localStorage.setItem('hearfolio-background-receive','false');const input=document.querySelector<HTMLInputElement>('#background-receive');if(input)input.checked=false;}
}
async function refreshInboxSnapshot(){if(!scannerAvailable||preview||document.hidden||connectionPaused)return;try{await consumeInboxSnapshot(await call<InboxSnapshot>('transfer_background',{}));}catch{/* Retry when the foreground is available. */}}
async function syncBackground(){if(!scannerAvailable||preview)return;try{const result=await call<{enabled:boolean}>('transfer_background',{preferences:{enabled:backgroundEnabled&&connected&&!connectionPaused,...preferences}});backgroundActive=result.enabled;}catch(e){backgroundActive=false;backgroundEnabled=false;localStorage.setItem('hearfolio-background-receive','false');options?.notice(errorText(e),true);}}
export function transferSettingsHtml(){return `<section id="transfer-settings" class="settings-section settings-panel transfer-settings"><div class="section-heading"><h2>${t('Локальная передача','Local transfers')}</h2></div><p>${t('Записи и расшифровки передаются напрямую в одной локальной сети. Внешний сервер не используется.','Recordings and transcripts transfer directly on the same local network. No external server is used.')}</p>${connectionSaved?`<div class="transfer-connection-caption"><span class="device-dot ${connected&&!connectionError&&!connectionPaused?'online':''}"></span><span>${esc(serverLabel())} · ${connectionText()}</span></div>`:''}<form id="transfer-connect">${connectFields()}<button class="secondary" ${modalWorking||operation?'disabled':''}>${modalWorking?t('Подключение…','Connecting…'):connectionSaved?t('Сохранить подключение','Save connection'):t('Включить локальную передачу','Enable local transfers')}</button></form>${connectionSaved?`<button type="button" class="text-button transfer-disconnect" id="transfer-toggle-connection" ${operation||modalWorking?'disabled':''}>${connectionPaused?t('Включить передачу','Resume transfers'):t('Выключить передачу','Pause transfers')}</button><p class="transfer-pause-help">${t('Записи и подключение сохранятся. Передачу можно включить снова.','Your recordings and connection are kept. Resume transfers at any time.')}</p>`:''}${messageHtml()}<details class="transfer-advanced"><summary>${t('Приём и подтверждения','Receiving and confirmations')}</summary>${automaticSettingsHtml()}${backgroundSettingsHtml()}</details></section>`;}
function joinFields(){return `${serverField()}${deviceNameField()}${codeField()}<p class="share-help">${t('Откройте «Устройства» → «Подключить устройство» на уже подключённом устройстве. После ввода кода подтвердите запрос там.','Open Devices → Pair a device on your connected device. After entering its code, accept the request there.')}</p>`;}

async function joinInvitation(data:FormData){const known=state?.peers.map(p=>p.id)||[];if(!data.has('server'))data.set('server',server);data.set('invitationCode',String(data.get('invitationCode')).replace(/\s/g,''));message=t('Подтвердите запрос на устройстве с приглашением…','Confirm the request on the inviting device…');update();await connectRelay(data);if(preview&&!fixture){message=t('Настройки сохранены. Подключение по приглашению доступно в приложении Hearfolio.','Settings saved. Joining by invitation is available in the Hearfolio app.');return;}if(state?.peers.some(p=>!known.includes(p.id))){message=t('Устройство подключено','Device paired');options?.notice(message);}else{pairingWait={known,until:Date.now()+180000};message=t('Запрос отправлен. Подтвердите подключение на втором устройстве.','Request sent. Confirm pairing on the other device.');}}
async function connectRelay(data:FormData){const address=configuredServer(String(data.get('server')||'')),deviceName=String(data.get('name')||'').trim();if(data.get('invitationCode')&&!address)throw new Error(t('Укажите локальный адрес другого устройства.','Enter the local address of your other device.'));if(!deviceName)throw new Error(t('Укажите имя этого устройства.','Enter this device’s name.'));if(preview){const parsed=new URL(address);const host=parsed.hostname.replace(/^\[|\]$/g,'');const parts=host.split('.').map(Number);const local=host==='localhost'||host==='::1'||(parts.length===4&&parts.every(part=>Number.isInteger(part)&&part>=0&&part<=255)&&(parts[0]===127||parts[0]===10||(parts[0]===192&&parts[1]===168)||(parts[0]===172&&parts[1]>=16&&parts[1]<=31)));if(!(parsed.protocol==='https:'||(parsed.protocol==='http:'&&local))||parsed.username||parsed.password||parsed.search||parsed.hash||parsed.pathname!=='/')throw new Error(t('Используйте HTTPS или локальный HTTP-адрес без пути, параметров и пароля.','Use HTTPS or a local HTTP address without a path, parameters or password.'));server=address;name=deviceName;connectionSaved=true;connectionPaused=false;localStorage.setItem('hearfolio-relay-url',server);localStorage.setItem('hearfolio-device-name',name);localStorage.setItem('hearfolio-transfer-paused','false');clearConnectionDraft();return;}const next=await api<State>('connect',{server:address,name:deviceName,updateOnly:connectionSaved&&!data.get('invitationCode'),invitationCode:String(data.get('invitationCode')||'').replace(/\s/g,'')});const saved=await api<{server:string}>('saved');server=saved.server;name=deviceName;state=next;connected=true;connectionSaved=true;connectionError=false;connectionPaused=false;localStorage.setItem('hearfolio-transfer-paused','false');code='';qr='';codeUntil=0;void syncBackground();localStorage.setItem('hearfolio-relay-url',server);localStorage.setItem('hearfolio-device-name',name);clearConnectionDraft();message='';}
function pairTabsHtml(){return `<div class="transfer-tabs" role="group" aria-label="${t('Способ подключения','Pairing method')}"><button type="button" data-pair-mode="invite" aria-pressed="${pairMode==='invite'}">${t('Показать приглашение','Show invitation')}</button><button type="button" data-pair-mode="code" aria-pressed="${pairMode==='code'}">${t('Ввести код','Enter code')}</button></div>`;}
function invitationHtml(){return `<p class="share-help">${t('На втором устройстве откройте «Устройства» и выберите «Есть приглашение». Отсканируйте QR или введите код ниже.','On your other device, open Devices and choose Have an invitation. Scan this QR or enter the code below.')}</p><div class="share-qr">${qr||`<p>${modalWorking?t('Создаём приглашение…','Creating invitation…'):t('Приглашение недоступно. Попробуйте ещё раз.','Invitation unavailable. Try again.')}</p>`}</div><div class="share-code"><small>${esc(server)}</small><strong>${esc(code.replace(/(....)(....)/,'$1 $2'))||'—'}</strong><small id="share-expiry">${expiryText()}</small></div><button type="button" class="secondary share-renew" id="share-renew" ${modalWorking?'disabled':''}>${t('Обновить приглашение','Renew invitation')}</button><p class="share-help">${t('Затем подтвердите запрос подключения на этом устройстве.','Then accept the pairing request on this device.')}</p>`;}
function modalHtml(){const pairing=shareView==='pair';return `<div class="share-heading"><h2 id="share-title">${pairing?t('Подключить устройство','Pair a device'):t('Отправить запись','Send recording')}</h2><button type="button" class="icon-button" data-share-close aria-label="${t('Закрыть','Close')}">${icon('close')}</button></div>${shareEntry&&!pairing?`<div class="share-record-detail">${icon('wave')}<div><strong class="share-record">${esc(shareEntry.name)}</strong><small>${t('Аудио и сохранённая расшифровка','Audio and saved transcript')}</small></div></div>`:''}${messageHtml()}${operationHtml()}${!connected?`<p class="share-help">${t('Подключитесь по приглашению с другого устройства, чтобы отправлять записи.','Use an invitation from your other device to send recordings.')}</p>${scanButtonHtml()}<form id="share-connect">${joinFields()}<button class="primary" ${modalWorking?'disabled':''}>${modalWorking?t('Подключение…','Connecting…'):t('Подключить по приглашению','Join with invitation')}</button></form>`:!pairing?`<p class="share-help">${t('Выберите устройство. На нём нужно будет принять запись.','Choose a device, then accept the recording there.')}</p><div class="share-peers">${state?.peers.map(p=>`<button type="button" class="share-peer" data-send-peer="${esc(p.id)}" ${!p.online||!shareEntry||modalWorking||operation||options?.busy()||connectionError||connectionPaused?'disabled':''}><span>${esc(p.name)}</span><small><i class="device-dot ${p.online?'online':''}"></i>${p.online?t('Готово к приёму','Ready to receive'):t('Откройте Hearfolio на этом устройстве','Open Hearfolio on this device')}</small>${icon('chevron')}</button>`).join('')||`<div class="transfer-empty"><span>${icon('devices')}</span><p>${t('Добавьте второе устройство, чтобы отправить на него эту запись.','Add another device to send this recording to it.')}</p></div>`}</div><button type="button" class="secondary" id="share-add">${icon('plus')}${t('Подключить устройство','Pair a device')}</button>`:`${shareEntry?`<button type="button" class="text-button" id="share-back">${t('← К выбору устройства','← Choose a device')}</button>`:''}${pairTabsHtml()}${pairMode==='invite'?invitationHtml():`<p class="share-help">${t('Покажите приглашение на втором устройстве, введите его адрес и код.','Show an invitation on your other device, then enter its address and code.')}</p>${scanButtonHtml()}<form id="share-pair">${serverField()}${codeField()}<button class="primary" ${modalWorking?'disabled':''}>${t('Подключить по коду','Pair with code')}</button></form>`}`}<div id="share-requests">${requestsHtml()}</div>`;}

function updateShareDialog(force=false){if(!shareDialog||shareDialog.dataset.state==='invitation')return;const expiry=shareDialog.querySelector('#share-expiry');if(expiry)expiry.textContent=expiryText();const focused=shareDialog.contains(document.activeElement)&&document.activeElement?.tagName==='INPUT';if(focused&&!force)return;const fingerprint=JSON.stringify([networkWaiting,state,message,connected,shareView,pairMode,qr,modalWorking,connectionError,connectionPaused]);if(shareDialog.dataset.state===fingerprint)return;shareDialog.dataset.state=fingerprint;const fields=preserveFields(shareDialog);const focus=document.activeElement as HTMLElement|null;const focusId=shareDialog.contains(focus)&&focus?.tagName==='BUTTON'?focus.id:'';const focusMode=shareDialog.contains(focus)?focus?.dataset.pairMode:undefined;const focusClose=shareDialog.contains(focus)&&focus?.hasAttribute('data-share-close');shareDialog.innerHTML=modalHtml();restoreFields(shareDialog,fields);bindShareDialog();if(focusId)shareDialog.querySelector<HTMLElement>(`#${focusId}`)?.focus({preventScroll:true});else if(focusMode)shareDialog.querySelector<HTMLElement>(`[data-pair-mode="${focusMode}"]`)?.focus({preventScroll:true});else if(focusClose)shareDialog.querySelector<HTMLElement>('[data-share-close]')?.focus({preventScroll:true});}
function openShare(entry:Entry|null,createInvitation=true){if(shareDialog){shareDialog.close();}shareEntry=entry;shareView=entry?'devices':'pair';pairMode=connected?'invite':'code';const returnFocus=document.activeElement as HTMLElement|null;const dialog=document.createElement('dialog');shareDialog=dialog;dialog.className='share-dialog';dialog.setAttribute('aria-labelledby','share-title');dialog.addEventListener('close',()=>{dialog.remove();if(shareDialog===dialog)shareDialog=null;if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else document.querySelector<HTMLButtonElement>(entry?'#transfer-send':'#devices-add')?.focus({preventScroll:true});});document.body.append(dialog);updateShareDialog();dialog.showModal();if(!entry&&connected&&createInvitation)void makeInvitation();}
function chooseRecipient(entry:Entry){message='';openShare(entry);}
export function shareRecordingToDevice(entry:Entry){chooseRecipient(entry);}
async function modalAction(action:()=>Promise<void>){if(modalWorking)return;modalWorking=true;updateShareDialog(true);try{await action();}catch(e){message=errorText(e);}finally{modalWorking=false;update();updateShareDialog(true);updateDevicesPanel(true);}}
async function makeInvitation(){if(connectionPaused||!connected||connectionError)return;await modalAction(async()=>{qr='';code='';codeUntil=0;const saved=await api<{server:string}>('saved');if(!saved.server)throw new Error(t('Подключитесь к Wi-Fi, чтобы показать приглашение.','Connect to Wi-Fi to show an invitation.'));server=saved.server;const result=await api<{code:string;expiresAt:number}>('code');code=result.code;codeUntil=result.expiresAt;const url=new URL('hearfolio-transfer://pair');url.searchParams.set('server',server);url.searchParams.set('code',code);qr=await QRCode.toString(url.href,{type:'svg',margin:4,width:240,errorCorrectionLevel:'M'});});}
function bindShareDialog(){const d=shareDialog!;bindScanner(d);d.querySelectorAll<HTMLElement>('[data-pair-mode]').forEach(button=>button.onclick=()=>{pairMode=button.dataset.pairMode as typeof pairMode;message='';if(pairMode==='invite'&&(!code||Date.now()>=codeUntil))void makeInvitation();else updateShareDialog(true);});d.querySelector('[data-share-close]')?.addEventListener('click',()=>d.close());d.querySelector('#share-add')?.addEventListener('click',()=>{shareView='pair';pairMode='invite';message='';void makeInvitation();});d.querySelector('#share-back')?.addEventListener('click',()=>{shareView='devices';updateShareDialog();});d.querySelector('#share-renew')?.addEventListener('click',()=>{void makeInvitation();});d.querySelectorAll<HTMLElement>('[data-send-peer]').forEach(b=>b.onclick=()=>{const entry=shareEntry;if(entry){d.close();void send(entry,b.dataset.sendPeer!);}});d.querySelector<HTMLFormElement>('#share-connect')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget as HTMLFormElement);void modalAction(async()=>{await joinInvitation(data);});});d.querySelector<HTMLFormElement>('#share-pair')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget as HTMLFormElement);void modalAction(async()=>{data.set('name',name);await joinInvitation(data);});});bindRequests(d);}
async function acceptInvitation(raw:string){try{const url=new URL(raw);if(url.protocol!=='hearfolio-transfer:'||url.hostname!=='pair')return;const address=url.searchParams.get('server')||'',invite=url.searchParams.get('code')||'';if(!/^\d{8}$/.test(invite)||!address)return;if(operation||options?.busy()){options?.notice(t('Завершите текущую операцию перед подключением','Finish the current operation before pairing'),true);return;}openShare(null,false);shareView='pair';message=t('Локальное устройство: ','Local device: ')+address;shareDialog!.innerHTML=`<div class="share-heading"><h2 id="share-title">${t('Подключить устройство','Pair a device')}</h2><button type="button" class="text-button" data-share-close>${t('Закрыть','Close')}</button></div><p>${esc(message)}</p><form id="invite-connect"><label class="field"><span>${t('Имя этого устройства','This device name')}</span><input name="name" required maxlength="100" value="${esc(name)}" placeholder="${t('Мой телефон','My phone')}"></label><button class="primary">${t('Подключиться','Connect')}</button></form>`;shareDialog!.querySelector('[data-share-close]')?.addEventListener('click',()=>shareDialog?.close());shareDialog!.dataset.state='invitation';shareDialog!.querySelector<HTMLFormElement>('#invite-connect')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget as HTMLFormElement);data.set('server',address);data.set('invitationCode',invite);shareDialog!.dataset.state='';void modalAction(async()=>{await joinInvitation(data);shareView='devices';});});}catch(e){message=errorText(e);update();}}
async function syncTransferSnapshot(){
  if(preview||!scannerAvailable||transferSnapshotPolling||document.hidden)return;
  transferSnapshotPolling=true;
  try{
    const snapshot=await call<TransferSnapshot>('transfer_activity_snapshot');
    if(!snapshot.id||snapshot.state==='idle')return;
    const watched=observePendingTransfer(snapshot);
    if(watched.terminal||operationHandled(snapshot.id))return;
    if(snapshot.state==='running'){
      if(!watched.matched&&options?.busy()&&!operation)return;
      nativeTransferId=snapshot.id;phase=snapshot.stage|| (snapshot.direction==='send'?'sending':'receiving');offset=snapshot.current||0;total=snapshot.total||0;
      const restored=!operation;operation=true;if(restored)options?.setBusy(true);update();return;
    }
    if(foregroundTransfer||(options?.busy()&&!operation))return;
    operation=false;nativeTransferId='';session='';options?.setBusy(false);
    await options?.refresh();
    if(snapshot.state==='finished'&&snapshot.direction==='send'){pending=null;savePending();}
    message=snapshot.state==='finished'?(snapshot.direction==='send'?t('Запись доставлена на другое устройство','Recording delivered to your other device'):t('Запись получена и сохранена в архиве','Recording received and saved to your archive')):errorText(snapshot.error||'errors.transferInterrupted');
    markOperationHandled(snapshot.id);update();options?.notice(message,snapshot.state!=='finished');
  }catch{/* Read again after returning to the app. */}finally{transferSnapshotPolling=false;}
}
function cancelTransfer(){if(nativeTransferId){void call('cancel_transfer_activity',{id:nativeTransferId}).catch(error=>options?.notice(errorText(error),true));}else if(session)void runAction('cancel',{id:session});}
async function transfer(command:string,args:Record<string,unknown>){if(operation||options?.busy())return;if(connectionPaused){options?.notice(t('Включите передачу в настройках устройств.','Resume transfers in device settings.'),true);return;}networkWaiting=false;foregroundTransfer=true;operation=true;session='';offset=0;total=0;phase=command==='transfer_send'?'waiting':'receiving';options?.setBusy(true);update();let failed=false;try{if(fixture){session='fixture-progress';for(let step=0;step<=5;step++){phase=command==='transfer_send'?(step===0?'waiting':'sending'):'receiving';offset=step*480000;total=2400000;update();await new Promise(resolve=>setTimeout(resolve,240));}if(command==='transfer_receive')fixtureState.offers=fixtureState.offers.filter(offer=>offer.id!==args.id);}else await call(command,args);if(command==='transfer_send'){pending=null;savePending();}message=command==='transfer_send'?t('Запись доставлена на другое устройство','Recording delivered to your other device'):t('Запись получена и сохранена в архиве','Recording received and saved to your archive');}catch(e){failed=true;message=errorText(e);}finally{foregroundTransfer=false;operation=false;nativeTransferId='';session='';options?.setBusy(false);await options?.refresh();update();options?.notice(message,failed);}}
async function send(entry:Entry,to:string){pending={id:entry.id,to,name:entry.name,server};savePending();await transfer('transfer_send',{id:entry.id,to});}
async function receive(id:string){await transfer('transfer_receive',{id});}
async function poll(){if((!connected&&!connectionSaved)||polling||connectionPaused||(preview&&!fixture))return;polling=true;try{state=await api<State>('poll');if(state.connection){server=state.connection.server;localStorage.setItem('hearfolio-relay-url',server);}connected=true;if(connectionError)message='';connectionError=false;name=state.device.name;if(pairingWait){if(state.peers.some(p=>!pairingWait!.known.includes(p.id))){pairingWait=null;message=t('Устройство подключено','Device paired');if(shareEntry){shareView='devices';}else shareDialog?.close();options?.notice(message);}else if(Date.now()>=pairingWait.until){pairingWait=null;message=t('Время ожидания истекло. Создайте новый код и повторите подключение.','Pairing timed out. Create a new code and try again.');}}update();void processAutomaticRequests();}catch(e){connectionError=true;message=t('Нет связи с устройством. Проверьте Wi-Fi и откройте Hearfolio на втором устройстве. ','Cannot reach the device. Check Wi-Fi and open Hearfolio on your other device. ')+errorText(e);update();}finally{polling=false;}}
export async function initializeTransfers(config:NonNullable<typeof options>){options=config;scannerAvailable=(await loadRuntimePlatform()).os==='android';if(preview){connectionSaved=Boolean(server);if(fixture){server='http://192.168.1.10:47831';name=fixtureState.device.name;state=structuredClone(fixtureState);connected=true;connectionSaved=true;connectionPaused=false;code='12345678';codeUntil=Date.now()-1000;message=t('Проверочный сценарий · вымышленные устройства','Test scenario · synthetic devices');}setInterval(()=>{updateShareDialog();if(fixture)void poll();},1000);update();return;}try{const discovery=await call<{waiting:boolean}>('transfer_discovery');networkWaiting=discovery.waiting;}catch{/* Manual LAN connections still work when multicast is unavailable. */}await subscribe<{waiting:boolean}>('transfer-network-state',p=>{networkWaiting=p.waiting;update();});await subscribe<{id:string;status:string;current:number;total:number}>('transfer-progress',p=>{session=p.id;phase=p.status;offset=p.current;total=p.total;update();});try{const saved=await api<{server?:string;configured?:boolean}>('saved');if(saved.configured||saved.server){server=saved.server??server;connectionSaved=true;localStorage.setItem('hearfolio-relay-url',server);if(!connectionPaused){state=await api<State>('poll');name=state.device.name;connected=true;}}}catch{connectionError=connectionSaved;message=connectionSaved?t('Нет связи с локальным устройством. Подключитесь к той же Wi-Fi сети.','Cannot reach the local device. Connect to the same Wi-Fi network.'):'';}try{await onOpenUrl(urls=>{if(urls[0])void acceptInvitation(urls[0]);});const urls=await getCurrent();if(urls?.[0])void acceptInvitation(urls[0]);}catch{/* Desktop builds can use manual pairing. */}await subscribe<{id:string;ok:boolean;error?:string}>('background-transfer-result',p=>{void consumeInboxSnapshot({enabled:backgroundActive,result:p});});await syncTransferSnapshot();await syncBackground();setInterval(()=>{void poll();void refreshInboxSnapshot();void syncTransferSnapshot();},2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){void options?.refresh();void poll();void refreshInboxSnapshot();void syncTransferSnapshot();}});update();}

export function devicesHtml(){return `<div class="page-heading"><div><h1>${t('Устройства','Devices')}</h1><p>${t('Передавайте записи и расшифровки между своими устройствами.','Transfer recordings and transcripts between your devices.')}</p></div></div><div id="devices-content">${devicesContentHtml()}</div>`;}
function devicesContentHtml(){if(!connected&&!connectionSaved)return setupFormHtml();return `<div class="devices-overview"><section class="transfer-local-device"><span class="transfer-device-icon">${icon('devices')}</span><div><strong>${esc(state?.device.name||name||t('Это устройство','This device'))}</strong><small>${t('Это устройство','This device')} · ${esc(serverLabel())}</small><span class="transfer-connection-caption"><i class="device-dot ${connected&&!connectionError&&!connectionPaused?'online':''}"></i>${connectionText()}</span></div><button type="button" class="text-button" data-transfer-settings>${t('Настроить','Settings')}</button></section>${connectionError?`<div class="transfer-feedback" role="status">${esc(message)}<button class="secondary" id="transfer-reconnect">${t('Повторить подключение','Try again')}</button></div>`:messageHtml()}<section class="devices-list" aria-label="${t('Подключённые устройства','Paired devices')}"><div class="transfer-section-heading"><h2>${t('Подключённые устройства','Paired devices')}</h2><button type="button" class="secondary" id="devices-add" ${!connected||connectionError||connectionPaused||modalWorking?'disabled':''}>${icon('plus')}${t('Подключить устройство','Pair a device')}</button></div>${state?.peers.length?state.peers.map(p=>`<div class="device-row"><span class="transfer-device-icon">${icon('devices')}</span><div><strong>${esc(p.name)}</strong><small><i class="device-dot ${p.online?'online':''}"></i>${p.online?t('В сети · готово к приёму','Online · ready to receive'):t('Не в сети. Откройте Hearfolio на устройстве.','Offline. Open Hearfolio on this device.')}</small></div><button class="icon-button" data-unpair="${esc(p.id)}" title="${t('Отключить устройство','Unpair device')}" aria-label="${t('Отключить','Unpair')} ${esc(p.name)}" ${operation?'disabled':''}>${icon('close')}</button></div>`).join(''):`<div class="transfer-empty"><span>${icon('devices')}</span><h3>${t('Добавьте второе устройство','Add another device')}</h3><p>${t('Подключите телефон или компьютер через QR или код. Затем откройте запись и нажмите «Поделиться».','Pair your phone or computer using a QR or code. Then open a recording and choose Share.')}</p></div>`}</section><div id="transfer-state">${operationHtml()}${requestsHtml()}${pending&&!operation?`<div class="transfer-pending"><div><strong>${t('Запись не отправлена','Recording not sent')}</strong><p>${esc(pending.name)}</p><small>${t('Повторите отправку, когда устройство снова будет в сети.','Try again when the device is online.')}</small></div><div class="transfer-offer-actions"><button class="secondary" id="transfer-retry">${t('Повторить','Retry')}</button><button class="text-button" id="transfer-discard">${t('Убрать','Dismiss')}</button></div></div>`:''}</div></div>`;}
function updateDevicesPanel(force=false){const root=document.querySelector<HTMLElement>('#devices-content');if(!root)return;if(!force&&root.contains(document.activeElement)&&document.activeElement?.tagName==='INPUT'&&(document.activeElement as HTMLInputElement).type!=='checkbox')return;const fingerprint=JSON.stringify([networkWaiting,state,message,connected,connectionSaved,connectionError,connectionPaused,setupMode,modalWorking,operation,phase,offset,total,pending]);if(root.dataset.state===fingerprint&&!force)return;const fields=preserveFields(root);const scroll=root.scrollTop;root.dataset.state=fingerprint;root.innerHTML=devicesContentHtml();root.scrollTop=scroll;restoreFields(root,fields);bindConnection();bindPanel();bindDevicesActions();}
function bindDevicesActions(){bindScanner(document);document.querySelector('[data-transfer-settings]')?.addEventListener('click',()=>{const target=document.querySelector<HTMLElement>('.bottom-nav [data-view="settings"],.mobile-nav [data-view="settings"]');if(target){target.dataset.settingsTarget='devices';target.click();}});document.querySelector('#transfer-toggle-connection')?.addEventListener('click',()=>{void toggleConnection();});document.querySelectorAll<HTMLElement>('[data-setup-mode]').forEach(button=>button.onclick=()=>{const form=document.querySelector<HTMLFormElement>('#transfer-connect');if(form)rememberConnectionDraft(form);setupMode=button.dataset.setupMode as typeof setupMode;message='';updateDevicesPanel(true);});document.querySelector('#transfer-reconnect')?.addEventListener('click',()=>{void poll();});document.querySelectorAll<HTMLInputElement>('[data-transfer-preference]').forEach(input=>input.onchange=()=>{const key=input.dataset.transferPreference as keyof TransferPreferences;preferences[key]=input.checked;localStorage.setItem(key==='autoPair'?'hearfolio-auto-pair':'hearfolio-auto-receive',String(input.checked));const prefix=key==='autoPair'?'pair:':'receive:';for(const id of autoAttempted)if(id.startsWith(prefix))autoAttempted.delete(id);options?.notice(t('Настройка сохранена','Setting saved'));void syncBackground();void processAutomaticRequests();});document.querySelector('#devices-add')?.addEventListener('click',()=>{message='';openShare(null);});}


function automaticSettingsHtml(){return `<div class="transfer-preferences"><h2>${t('Подтверждения','Confirmations')}</h2><label class="transfer-preference"><span><strong>${t('Подключаться без подтверждения','Pair without confirmation')}</strong><small>${t('Устройства с действующим QR или кодом подключаются автоматически.','Devices with a valid QR or code pair automatically.')}</small></span><input type="checkbox" role="switch" data-transfer-preference="autoPair" ${preferences.autoPair?'checked':''}><i aria-hidden="true"></i></label><label class="transfer-preference"><span><strong>${t('Получать файлы без подтверждения','Receive files without confirmation')}</strong><small>${t('Автоматически сохранять записи от подключённых устройств. Пока приложение занято, запись ждёт.','Save recordings from paired devices automatically. Incoming recordings wait while the app is busy.')}</small></span><input type="checkbox" role="switch" data-transfer-preference="autoReceive" ${preferences.autoReceive?'checked':''}><i aria-hidden="true"></i></label></div>`;}
async function processAutomaticRequests(){if(autoProcessing||!connected||!state||preview||backgroundActive||connectionPaused||connectionError)return;autoProcessing=true;try{const active=new Set([...state.pairRequests.map(p=>`pair:${p.id}`),...state.offers.map(p=>`receive:${p.id}`)]);for(const id of autoAttempted)if(!active.has(id))autoAttempted.delete(id);const actions=automaticActions(state,preferences,operation||Boolean(options?.busy()),autoAttempted);for(const id of actions.pair){if(!preferences.autoPair)break;autoAttempted.add(`pair:${id}`);await runAction('confirmPair',{id,accept:true});}if(actions.receive&&preferences.autoReceive&&!operation&&!options?.busy()){autoAttempted.add(`receive:${actions.receive}`);await receive(actions.receive);}}finally{autoProcessing=false;}}

async function toggleConnection(){if(operation||modalWorking)return;await modalAction(async()=>{if(connectionPaused){connectionPaused=false;await poll();if(connectionError){connectionPaused=true;throw new Error(message);}await syncBackground();}else{if(scannerAvailable&&!preview){const stopped=await call<{enabled:boolean}>('transfer_background',{preferences:{enabled:false,...preferences}});if(stopped.enabled)throw new Error(t('Не удалось выключить приём в фоне. Повторите попытку.','Background receiving is still active. Try again.'));backgroundActive=false;}connectionPaused=true;connected=false;pairingWait=null;code='';qr='';codeUntil=0;shareDialog?.close();}localStorage.setItem('hearfolio-transfer-paused',String(connectionPaused));message=connectionPaused?t('Передача выключена. Записи и подключение сохранены.','Transfers paused. Your recordings and connection are kept.'):t('Передача включена','Transfers resumed');options?.notice(message);});}
function updateTransferSettings(){const root=document.querySelector<HTMLElement>('#transfer-settings');if(!root)return;const fingerprint=JSON.stringify([networkWaiting,server,name,connected,connectionSaved,connectionError,connectionPaused,message,modalWorking,operation,preferences,backgroundEnabled]);if(root.dataset.state===fingerprint)return;const fields=preserveFields(root),opened=[...root.querySelectorAll<HTMLDetailsElement>('details')].map(details=>details.open);const focusPreference=(document.activeElement as HTMLInputElement|null)?.dataset.transferPreference;const html=document.createElement('div');html.innerHTML=transferSettingsHtml();root.innerHTML=html.firstElementChild!.innerHTML;root.dataset.state=fingerprint;restoreFields(root,fields);root.querySelectorAll<HTMLDetailsElement>('details').forEach((details,index)=>details.open=opened[index]||false);bindConnection();bindDevicesActions();bindBackground();if(focusPreference)root.querySelector<HTMLInputElement>(`[data-transfer-preference="${focusPreference}"]`)?.focus({preventScroll:true});}
